import{_ as e,c as r,o as i,af as h}from"./chunks/framework.BKeRpnBD.js";const _=JSON.parse('{"title":"第五十七卦 巽 巽為風 巽上巽下","description":"周易 - 第五十七卦 巽 巽為風 巽上巽下","frontmatter":{"title":"第五十七卦 巽 巽為風 巽上巽下","description":"周易 - 第五十七卦 巽 巽為風 巽上巽下"},"headers":[],"relativePath":"classics/zhouyi/058.md","filePath":"classics/zhouyi/058.md"}'),l={name:"classics/zhouyi/058.md"};function t(n,a,s,d,o,c){return i(),r("div",null,[...a[0]||(a[0]=[h('<h1 id="巽" tabindex="-1">巽 <a class="header-anchor" href="#巽" aria-label="Permalink to “巽”">​</a></h1><h2 id="卦辭" tabindex="-1">卦辭 <a class="header-anchor" href="#卦辭" aria-label="Permalink to “卦辭”">​</a></h2><p>小亨，利攸往，利見大人。</p><h3 id="彖傳" tabindex="-1">彖傳 <a class="header-anchor" href="#彖傳" aria-label="Permalink to “彖傳”">​</a></h3><p>重巽以申命，剛巽乎中正而志行。柔皆順乎剛，是以小亨，利有攸往，利見大人。</p><h3 id="象傳" tabindex="-1">象傳 <a class="header-anchor" href="#象傳" aria-label="Permalink to “象傳”">​</a></h3><p>隨風，巽；君子以申命行事。</p><h3 id="初六" tabindex="-1">初六 <a class="header-anchor" href="#初六" aria-label="Permalink to “初六”">​</a></h3><p>進退，利武人之貞。象曰：進退，志疑也。 利武人之貞，志治也。</p><h3 id="九二" tabindex="-1">九二 <a class="header-anchor" href="#九二" aria-label="Permalink to “九二”">​</a></h3><p>巽在床下。用史巫紛若，吉無咎。象曰：紛若之吉，得中也。</p><h3 id="九三" tabindex="-1">九三 <a class="header-anchor" href="#九三" aria-label="Permalink to “九三”">​</a></h3><p>頻巽，吝。象曰：頻巽之吝，志窮也。</p><h3 id="六四" tabindex="-1">六四 <a class="header-anchor" href="#六四" aria-label="Permalink to “六四”">​</a></h3><p>悔亡，田獲三品。象曰：田獲三品，有功也。</p><h3 id="九五" tabindex="-1">九五 <a class="header-anchor" href="#九五" aria-label="Permalink to “九五”">​</a></h3><p>貞吉悔亡，無不利。無初有終，先庚三日，後庚三日，吉。象曰：九五之吉，位正中也。</p><h3 id="上九" tabindex="-1">上九 <a class="header-anchor" href="#上九" aria-label="Permalink to “上九”">​</a></h3><p>巽在床下，喪其資斧，貞兇。象曰：巽在□下，上窮也。喪其資斧，正乎兇也。</p>',19)])])}const b=e(l,[["render",t]]);export{_ as __pageData,b as default};
